#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int edge_count = 2 * (n - 1);
    int *head = malloc((n + 1) * sizeof(int));
    int *to = malloc(edge_count * sizeof(int));
    int *next = malloc(edge_count * sizeof(int));
    int *parent = calloc(n + 1, sizeof(int));
    int *order = malloc(n * sizeof(int));
    int *stack = malloc(n * sizeof(int));
    int *size = malloc((n + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) head[i] = -1;

    int idx = 0;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[idx] = b;
        next[idx] = head[a];
        head[a] = idx++;

        to[idx] = a;
        next[idx] = head[b];
        head[b] = idx++;
    }

    int top = 0, count = 0;
    stack[top++] = 1;
    parent[1] = -1;

    while (top > 0) {
        int u = stack[--top];
        order[count++] = u;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (v == parent[u]) continue;
            parent[v] = u;
            stack[top++] = v;
        }
    }

    for (int i = 1; i <= n; i++) size[i] = 1;

    int answer = n;
    for (int i = count - 1; i > 0; i--) {
        int u = order[i];
        int difference = abs(n - 2 * size[u]);
        if (difference < answer) answer = difference;
        size[parent[u]] += size[u];
    }

    printf("%d\n", answer);

    free(head);
    free(to);
    free(next);
    free(parent);
    free(order);
    free(stack);
    free(size);

    return 0;
}
